  void ShowChoices(){if(popup!=null){popup.Close();return;}if(!Enabled||Items.Count==0)return;OnDropDown(EventArgs.Empty);var form=new Form{FormBorderStyle=FormBorderStyle.None,ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,BackColor=ModernTheme.Edge,Padding=new Padding(1),Font=Font};popup=form;choices=new StudioListBox{Dock=DockStyle.Fill,Font=Font,ItemHeight=ItemHeight,BorderStyle=BorderStyle.None};foreach(var item in Items)choices.Items.Add(GetItemText(item));form.Controls.Add(choices);choices.SelectedIndex=SelectedIndex;
