   var at=PointToScreen(new Point(0,Height));var work=Screen.FromControl(this).WorkingArea;int width=Math.Min(work.Width,Math.Max(Width,DropDownWidth)),height=Math.Min(work.Height,Math.Min(Math.Max(1,MaxDropDownItems),Items.Count)*ItemHeight+2);form.Bounds=new Rectangle(Math.Max(work.Left,Math.Min(at.X,work.Right-width)),at.Y+height<=work.Bottom?at.Y:Math.Max(work.Top,PointToScreen(Point.Empty).Y-height),width,height);form.Deactivate+=(s,e)=>form.Close();form.FormClosed+=(s,e)=>{popup=null;choices=null;OnDropDownClosed(EventArgs.Empty);if(!IsDisposed)Focus();form.Dispose();};ModernTheme.Apply(form);form.Show(FindForm());choices.Focus();}
